var msg_payload = msg.payload;

if (msg_payload.scene_name === 'Intersection-Demo') {
    var region_name = msg_payload.region_name;
    var timestamp = msg_payload.timestamp;
    var counts = msg_payload.counts;
    var count_keys = Object.keys(counts);

    count_keys.forEach(function (key) {
        var json_body = [
            { count: counts[key] + "i" },
            {
                location: "Anthem",
                region: region_name,
                object: key
            }
        ];
        node.send({ payload: json_body, measurement: "region_obj_count_2", timestamp: timestamp });
    });

    var objects_exited = msg_payload.exited;
    var items_exited = objects_exited.length;
    if (items_exited > 0) {
        objects_exited.forEach(function (obj) {
            var json_body2 = [
                { dwell_time: parseFloat(obj.dwell.toFixed(2)) },
                {
                    location: "Anthem",
                    region: region_name,
                    object: obj.object.category
                }
            ];
            node.send({ payload: json_body2, measurement: "region_obj_dwell_2", timestamp: timestamp });
        });
    }
}
return null;

var msg_payload = msg.payload;

if (msg_payload.name === 'Intersection-Demo') {
    var timestamp = msg_payload.timestamp;
    // Handle pedestrian tracking data
    if (msg_payload.objects && Array.isArray(msg_payload.objects)) {
        msg_payload.objects.forEach(function (obj) {
            if (obj.category === "pedestrian" && ("lat_long_alt" in obj)) {
                // Calculate speed (velocity magnitude)
                var vel = obj.velocity || [0, 0, 0];
                var speed = Math.sqrt(vel[0] * vel[0] + vel[1] * vel[1] + vel[2] * vel[2]);

                var json_body3 = [
                    {
                        pedid: obj.id,
                        latitude: obj.lat_long_alt ? obj.lat_long_alt[0] : 0,
                        longitude: obj.lat_long_alt ? obj.lat_long_alt[1] : 0,
                        heading: obj.heading || 0,
                        velocity: speed.toFixed(2)
                    },
                    {
                        location: "Anthem"
                    }
                ];

                node.send({
                    payload: json_body3,
                    measurement: "pedestrian_loc",
                    timestamp: timestamp
                });
            }
        });
    }
}
return null;

var msg_payload = msg.payload;

if (msg_payload.scene_name !== 'Intersection-Demo') { return null; }

var tripwire_name = msg_payload.tripwire_name;
var timestamp = msg_payload.timestamp;
var objects = msg_payload.objects || [];

// Tripwire config: name -> wrong-way direction value
// direction=1 means normal traffic, direction=-1 means wrong-way
var wrong_way_direction = {
    'NBLANE_START_TW': -1,
    'NBLANE_END_TW': -1,
    'SBLANE_START_TW': -1,
    'SBLANE_END_TW': -1,
    'EBLANE_START_TW': -1,
    'EBLANE_END_TW': -1,
    'WBLANE_START_TW': -1,
    'WBLANE_END_TW': -1
};

var bad_dir = wrong_way_direction[tripwire_name];
if (bad_dir === undefined) { return null; }

// Extract lane name from tripwire (e.g., NBLANE_START_TW -> NBLANE)
var lane = tripwire_name.replace('_START_TW', '').replace('_END_TW', '');

objects.forEach(function (obj) {
    if (obj.direction === bad_dir) {
        var vel = obj.velocity || [0, 0, 0];
        var speed = Math.sqrt(vel[0] * vel[0] + vel[1] * vel[1]);

        // Ignore stationary/slow objects (detection jitter)
        if (speed < 3.0) { return; }

        var json_body = [
            {
                object_id: obj.id || 'unknown',
                heading: obj.heading || 0,
                speed: parseFloat(speed.toFixed(2)),
                wrong_way: 1
            },
            {
                location: 'Anthem',
                region: lane,
                object: obj.category || 'vehicle'
            }
        ];
        node.send({
            payload: json_body,
            measurement: 'wrong_way_alert',
            timestamp: timestamp
        });
    }
});
return null;
